parameters.query:
SELECT title, url, file_path, stream_date, transcript
FROM livestreams
WHERE video_id = $1;

parameters.jsonBody:
={{ JSON.stringify({
  contents: [{
    role: 'user',
    parts: [
      {
        fileData: { fileUri: 'https://www.youtube.com/watch?v=' + $fromAI('video_id', 'video_id of the livestream', 'string') },
        videoMetadata: {
          startOffset: Math.max(0, Math.floor($fromAI('start_sec', 'Second where the segment to re-watch starts (from the start of the video)', 'number'))) + 's',
          endOffset: Math.ceil($fromAI('end_sec', 'Second where the segment ends, at most 180 seconds after start_sec', 'number')) + 's',
          fps: 2
        }
      },
      { text: 'This is a segment of a livestream. Answer in Vietnamese, precisely, based only on what is seen and heard in this segment; give the time (seconds from the start of the segment) when relevant. Question: ' + $fromAI('question', 'Specific question about the visuals in this segment', 'string') }
    ]
  }],
  generationConfig: { mediaResolution: 'MEDIA_RESOLUTION_HIGH', thinkingConfig: { thinkingLevel: 'LOW' } }
}) }}
